"use client";

import { useMemo, useRef, useState } from "react";

type CourseBuilderPanelProps = { trainingTitle: string; onBack: () => void };
type LessonStatus = "Published" | "Draft";
type Lesson = {
  id: number;
  title: string;
  type: string;
  status: LessonStatus;
  required: boolean;
  duration: string;
  description: string;
  availability: string;
  prerequisite: string;
  completionRule: string;
  typeSettings: string;
};
type AddStep = "type" | "settings";

const lessonGroups = [
  { title: "Learning content", description: "Self-paced content learners can read, watch, or open.", items: ["Reading / Topic", "eBook", "Video", "Audio", "PDF and Resources", "External Link"] },
  { title: "Live and practical learning", description: "Sessions and activities that turn knowledge into practice.", items: ["Live Session", "In-person Session", "Case Study / Scenario", "Practical Exercise", "Assignment"] },
  { title: "Assessment and engagement", description: "Ways for learners to practise, respond, and demonstrate progress.", items: ["Quiz", "Formal Assessment", "Survey / Feedback", "Discussion / Q&A"] },
] as const;

const starterLessons: Lesson[] = [
  { id: 1, title: "Welcome & orientation", type: "Reading / Topic", status: "Published", required: true, duration: "8 min", description: "A short introduction to the course.", availability: "Available immediately", prerequisite: "None", completionRule: "Read to the end", typeSettings: "Rich text content" },
  { id: 2, title: "Nutrition foundations", type: "Video", status: "Draft", required: true, duration: "14 min", description: "Core concepts learners need before the activities.", availability: "Available immediately", prerequisite: "Welcome & orientation", completionRule: "Watch to the end", typeSettings: "Video URL  |  Captions enabled" },
  { id: 3, title: "Weekly reflection", type: "Assignment", status: "Draft", required: false, duration: "15 min", description: "Reflect on the week's learning.", availability: "Available immediately", prerequisite: "Nutrition foundations", completionRule: "Submit response", typeSettings: "File upload  |  Manual grading" },
];

function TypeIcon({ type }: { type: string }) {
  const initials = type === "PDF and Resources" ? "PDF" : type === "Discussion / Q&A" ? "Q&A" : type.slice(0, 2).toUpperCase();
  return <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#e8f6ee] text-[10px] font-extrabold tracking-wide text-[#1f6a58]">{initials}</span>;
}

function SettingRow({ label, value }: { label: string; value: string }) {
  return <div className="flex items-center justify-between gap-4 border-b border-[#edf3f0] py-3 last:border-b-0"><span className="text-xs font-semibold text-[#52736a]">{label}</span><span className="text-right text-xs font-bold text-[#06201c]">{value}</span></div>;
}

function ToggleRow({ label, enabled, onToggle }: { label: string; enabled: boolean; onToggle: () => void }) {
  return <button type="button" aria-pressed={enabled} onClick={onToggle} className="flex w-full items-center justify-between border-b border-[#edf3f0] py-3 text-left last:border-b-0"><span className="text-xs font-semibold text-[#52736a]">{label}</span><span className={"relative h-6 w-11 rounded-full transition " + (enabled ? "bg-[#1f6a58]" : "bg-[#d7e5df]")}><span className={"absolute top-1 h-4 w-4 rounded-full bg-white transition " + (enabled ? "left-6" : "left-1")} /></span></button>;
}

function Field({ label, value, onChange, placeholder }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string }) {
  return <label className="block text-xs font-extrabold text-[#52736a]">{label}<input value={value} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] px-3 text-sm font-semibold text-[#06201c] outline-none focus:border-[#1f6a58]" /></label>;
}

function ModalShell({ title, eyebrow, onClose, children }: { title: string; eyebrow: string; onClose: () => void; children: React.ReactNode }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#06201c]/45 p-4" role="dialog" aria-modal="true"><div className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-3xl border border-[#e1ebe6] bg-white p-5 shadow-2xl sm:p-7"><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.14em] text-[#7f9d94]">{eyebrow}</p><h2 className="mt-1 text-2xl font-extrabold text-[#06201c]">{title}</h2></div><button type="button" onClick={onClose} className="rounded-full px-3 py-1 text-2xl text-[#52736a] hover:bg-[#f0f3f2]" aria-label="Close">x</button></div>{children}</div></div>;
}

export default function CourseBuilderPanel({ trainingTitle, onBack }: CourseBuilderPanelProps) {
  const [lessons, setLessons] = useState(starterLessons);
  const [courseStatus, setCourseStatus] = useState<LessonStatus>("Draft");
  const [isAddLessonOpen, setIsAddLessonOpen] = useState(false);
  const [addStep, setAddStep] = useState<AddStep>("type");
  const [selectedType, setSelectedType] = useState("Video");
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [previewLessonId, setPreviewLessonId] = useState(starterLessons[0].id);
  const [isPreviewStarted, setIsPreviewStarted] = useState(false);
  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [draftLesson, setDraftLesson] = useState<Lesson | null>(null);
  const [isCourseSettingsOpen, setIsCourseSettingsOpen] = useState(false);
  const [isPublishReviewOpen, setIsPublishReviewOpen] = useState(false);
  const [courseFeedback, setCourseFeedback] = useState("");
  const [courseSettings, setCourseSettings] = useState({ progressTracking: true, certificates: false, attendance: true, expiry: false, reporting: true });
  const selectedTypeDescription = useMemo(() => "Configure only the settings that matter for this learner experience.", [selectedType]);
  const publishedCount = lessons.filter((lesson) => lesson.status === "Published").length;
  const requiredCount = lessons.filter((lesson) => lesson.required).length;
  const previewLesson = lessons.find((lesson) => lesson.id === previewLessonId) ?? lessons[0];

  const newLesson = (): Lesson => ({ id: Date.now(), title: "New " + selectedType, type: selectedType, status: "Draft", required: true, duration: "Not set", description: "", availability: "Available immediately", prerequisite: "None", completionRule: "Mark as complete", typeSettings: "Not configured" });
  const openAddLesson = () => { setSelectedType("Video"); setAddStep("type"); setIsAddLessonOpen(true); };
  const addLesson = (details: Partial<Lesson> = {}) => { setLessons((current) => [...current, { ...newLesson(), ...details }]); setIsAddLessonOpen(false); setAddStep("type"); };
  const openEdit = (lesson: Lesson) => { setEditingLesson(lesson); setDraftLesson({ ...lesson }); };
  const saveLesson = () => { if (!draftLesson) return; setLessons((current) => current.map((lesson) => lesson.id === draftLesson.id ? draftLesson : lesson)); setEditingLesson(null); setDraftLesson(null); };
  const updateLessonStatus = (lessonId: number, status: LessonStatus) => { setLessons((current) => current.map((lesson) => lesson.id === lessonId ? { ...lesson, status } : lesson)); setCourseFeedback(status === "Published" ? "Lesson published." : "Lesson saved as draft."); };
  const removeLesson = (lesson: Lesson) => { if (!window.confirm(`Remove “${lesson.title}” from this course?`)) return; setLessons((current) => current.filter((item) => item.id !== lesson.id)); setCourseFeedback(`${lesson.title} removed from the course.`); };
  const moveLesson = (index: number, direction: -1 | 1) => {
    const nextIndex = index + direction;
    if (nextIndex < 0 || nextIndex >= lessons.length) return;
    setLessons((current) => { const next = [...current]; [next[index], next[nextIndex]] = [next[nextIndex], next[index]]; return next; });
  };
  const toggleSetting = (key: keyof typeof courseSettings) => setCourseSettings((current) => ({ ...current, [key]: !current[key] }));
  const publishCourse = () => { setCourseStatus("Published"); setIsPublishReviewOpen(false); };

  return (
    <div className="min-h-[720px] w-full rounded-3xl border border-[#e1ebe6] bg-[#f7fbf8] p-4 shadow-sm sm:p-6 lg:p-8">
      <div className="flex flex-col gap-4 border-b border-[#e1ebe6] pb-6 lg:flex-row lg:items-start lg:justify-between">
        <div><button type="button" onClick={onBack} className="text-sm font-bold text-[#1f6a58] hover:underline">&lt;- Back to training details</button><p className="mt-5 text-[10px] font-extrabold uppercase tracking-[0.22em] text-[#7f9d94]">Course builder</p><div className="mt-2 flex flex-wrap items-center gap-3"><h1 className="text-2xl font-extrabold tracking-tight text-[#06201c] sm:text-3xl">{trainingTitle}</h1><span className={"rounded-full px-3 py-1 text-[11px] font-extrabold " + (courseStatus === "Published" ? "bg-[#e8f6ee] text-[#1f6a58]" : "bg-[#fff8e1] text-[#8a5a00]")}>{courseStatus.toUpperCase()}</span></div><p className="mt-2 max-w-2xl text-sm leading-6 text-[#52736a]">Design the learning journey, configure each learner experience, and preview the course on mobile.</p></div>
        <div className="flex flex-wrap items-center justify-end gap-2"><span aria-live="polite" className="text-xs font-bold text-[#167550]">{courseFeedback}</span><button type="button" onClick={() => setCourseFeedback("Course draft saved locally.")} className="h-11 rounded-full border border-[#b7d5c8] bg-white px-4 text-sm font-extrabold text-[#1f6a58] hover:bg-[#f4faf7]">Save draft</button><button type="button" onClick={() => { setIsPreviewOpen((current) => !current); setIsPreviewStarted(false); }} className="h-11 rounded-full border border-[#d7e5df] bg-white px-4 text-sm font-bold text-[#1f6a58] hover:bg-[#f4faf7]">{isPreviewOpen ? "Close preview" : "Preview as learner"}</button><button type="button" onClick={openAddLesson} className="h-11 rounded-full bg-[#1f6a58] px-5 text-sm font-extrabold text-white shadow-sm hover:bg-[#195646]">+ Add lesson</button></div>
      </div>

      <div className="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1fr)_320px]">
        <main className="space-y-5">
          <section className="rounded-2xl border border-[#e1ebe6] bg-white p-5 shadow-sm sm:p-6"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.14em] text-[#7f9d94]">Course structure</p><h2 className="mt-1 text-xl font-extrabold text-[#06201c]">Build your learning journey</h2><p className="mt-1 text-xs text-[#52736a]">Set each lesson to Draft while building, then switch it to Published when its content is ready.</p></div><span className="rounded-full bg-[#e8f6ee] px-3 py-1 text-xs font-extrabold text-[#1f6a58]">{lessons.length} lessons</span></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-[#edf3f0]"><div className="h-full rounded-full bg-[#1f6a58]" style={{ width: Math.max(12, Math.round((publishedCount / Math.max(1, lessons.length)) * 100)) + "%" }} /></div><p className="mt-2 text-xs text-[#52736a]">{publishedCount} of {lessons.length} lessons are published</p><div className="mt-5 space-y-3">{lessons.map((lesson, index) => <article key={lesson.id} className="flex flex-wrap items-center gap-3 rounded-2xl border border-[#e1ebe6] bg-[#fbfdfb] p-3 transition hover:border-[#b7d5c8] hover:bg-white"><div className="hidden flex-col gap-1 sm:flex"><button type="button" aria-label={"Move " + lesson.title + " up"} disabled={index === 0} onClick={() => moveLesson(index, -1)} className="text-xs text-[#52736a] disabled:opacity-25">Up</button><button type="button" aria-label={"Move " + lesson.title + " down"} disabled={index === lessons.length - 1} onClick={() => moveLesson(index, 1)} className="text-xs text-[#52736a] disabled:opacity-25">Down</button></div><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[#e8f6ee] text-xs font-extrabold text-[#1f6a58]">{index + 1}</span><TypeIcon type={lesson.type} /><button type="button" onClick={() => openEdit(lesson)} className="min-w-0 flex-1 text-left"><h3 className="truncate text-sm font-extrabold text-[#06201c]">{lesson.title}</h3><p className="mt-1 truncate text-xs text-[#52736a]">{lesson.type} <span className="px-1 text-[#b7c9c1]">|</span> {lesson.duration}</p></button><label className="flex items-center gap-2 text-[10px] font-extrabold text-[#52736a]">Status<select aria-label={lesson.title + " status"} value={lesson.status} onChange={(event) => updateLessonStatus(lesson.id, event.target.value as LessonStatus)} className={"h-9 rounded-lg border px-2 text-[11px] font-extrabold outline-none " + (lesson.status === "Published" ? "border-[#bce8d1] bg-[#e8f6ee] text-[#1f6a58]" : "border-[#eadbb8] bg-[#fff8e1] text-[#8a5a00]")}><option>Draft</option><option>Published</option></select></label><span className="rounded-full bg-[#f0f3f2] px-2.5 py-1 text-[10px] font-extrabold text-[#52736a]">{lesson.required ? "Required" : "Optional"}</span><button type="button" aria-label={"Edit " + lesson.title} onClick={() => openEdit(lesson)} className="rounded-lg px-2 py-1 text-sm font-bold text-[#52736a] hover:bg-[#f0f3f2]">Edit</button><button type="button" aria-label={"Remove " + lesson.title} onClick={() => removeLesson(lesson)} className="rounded-lg px-2 py-1 text-sm font-bold text-[#b42318] hover:bg-[#fff2f0]">Remove</button></article>)}</div><button type="button" onClick={openAddLesson} className="mt-4 flex w-full items-center justify-center rounded-xl border border-dashed border-[#b7d5c8] bg-[#f9fcfa] px-4 py-3 text-sm font-extrabold text-[#1f6a58] hover:bg-[#e8f6ee]">+ Add the next lesson</button></section>
          <section className="grid gap-4 sm:grid-cols-3"><div className="rounded-2xl border border-[#e1ebe6] bg-white p-4 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.12em] text-[#7f9d94]">Published</p><p className="mt-2 text-2xl font-extrabold text-[#06201c]">{publishedCount} / {lessons.length}</p></div><div className="rounded-2xl border border-[#e1ebe6] bg-white p-4 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.12em] text-[#7f9d94]">Required</p><p className="mt-2 text-2xl font-extrabold text-[#06201c]">{requiredCount}</p></div><div className="rounded-2xl border border-[#e1ebe6] bg-white p-4 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.12em] text-[#7f9d94]">Mobile ready</p><p className="mt-2 text-2xl font-extrabold text-[#1f6a58]">Yes</p></div></section>
        </main>

        <aside className="space-y-5">{isPreviewOpen ? <section className="rounded-2xl border border-[#d7e5df] bg-[#06201c] p-4 shadow-sm"><div className="mb-3 flex items-center justify-between"><p className="text-[10px] font-extrabold uppercase tracking-[0.14em] text-white/60">Learner preview</p><span className="rounded-full bg-white/10 px-2 py-1 text-[10px] font-bold text-white">Mobile</span></div><div className="mb-3 flex gap-2 overflow-x-auto pb-1">{lessons.map((lesson) => <button key={lesson.id} type="button" onClick={() => { setPreviewLessonId(lesson.id); setIsPreviewStarted(false); }} className={"whitespace-nowrap rounded-full px-3 py-1.5 text-[10px] font-bold " + (previewLesson.id === lesson.id ? "bg-white text-[#06201c]" : "bg-white/10 text-white")}>{lesson.title}</button>)}</div><div className="mx-auto max-w-[260px] rounded-[28px] border-4 border-[#31594d] bg-white p-3"><div className="rounded-[20px] bg-[#f7fbf8] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#7f9d94]">{previewLesson.type}</p><h3 className="mt-3 text-lg font-extrabold text-[#06201c]">{previewLesson.title}</h3><p className="mt-1 text-xs text-[#52736a]">{previewLesson.duration}</p><div className="mt-4 flex h-28 items-center justify-center rounded-xl bg-[#06201c] text-3xl text-white">{previewLesson.type === "Video" ? "Play" : "Open"}</div><button type="button" onClick={() => setIsPreviewStarted(true)} className="mt-4 h-10 w-full rounded-full bg-[#1f6a58] text-xs font-extrabold text-white">{isPreviewStarted ? "Lesson in progress" : "Continue lesson"}</button><p className="mt-3 text-center text-[10px] text-[#52736a]">{isPreviewStarted ? "Progress is being tracked" : "Resume from saved progress"}</p></div></div></section> : <section className="rounded-2xl border border-[#e1ebe6] bg-white p-5 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.14em] text-[#7f9d94]">Course settings</p><h2 className="mt-1 text-lg font-extrabold text-[#06201c]">Learner experience</h2><div className="mt-4"><SettingRow label="Progress tracking" value={courseSettings.progressTracking ? "Enabled" : "Disabled"} /><SettingRow label="Certificates" value={courseSettings.certificates ? "Enabled" : "Not configured"} /><SettingRow label="Attendance" value={courseSettings.attendance ? "Available" : "Not used"} /><SettingRow label="Course expiry" value={courseSettings.expiry ? "Configured" : "No expiry"} /><SettingRow label="Instructor reporting" value={courseSettings.reporting ? "Enabled" : "Disabled"} /></div><button type="button" onClick={() => setIsCourseSettingsOpen(true)} className="mt-4 w-full rounded-xl border border-[#d7e5df] px-4 py-2.5 text-sm font-extrabold text-[#1f6a58] hover:bg-[#f4faf7]">Manage course settings</button></section>}<section className="rounded-2xl border border-[#e1ebe6] bg-white p-5 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.14em] text-[#7f9d94]">Publishing checklist</p><div className="mt-3 space-y-2 text-xs font-semibold text-[#52736a]"><p>{lessons.length > 0 ? "Done" : "Needs attention"} Add at least one lesson</p><p>{requiredCount > 0 ? "Done" : "Needs attention"} Set required learning</p><p>{publishedCount > 0 ? "Done" : "Needs attention"} Publish learner content</p></div><button type="button" onClick={() => setIsPublishReviewOpen(true)} className="mt-4 w-full rounded-xl bg-[#1f6a58] px-4 py-2.5 text-sm font-extrabold text-white">Publish course</button></section></aside>\n+      </div>

      {isAddLessonOpen ? <ModalShell title={addStep === "type" ? "What do you want learners to do?" : "Configure your lesson"} eyebrow={addStep === "type" ? "New lesson - Step 1 of 2" : "New lesson - Step 2 of 2"} onClose={() => setIsAddLessonOpen(false)}>{addStep === "type" ? <><p className="mt-2 text-sm text-[#52736a]">Choose a type first. We will show only the settings that matter for it.</p><div className="mt-6 grid gap-5 md:grid-cols-3">{lessonGroups.map((group) => <div key={group.title}><p className="text-xs font-extrabold text-[#06201c]">{group.title}</p><p className="mt-1 text-xs leading-5 text-[#7f9d94]">{group.description}</p><div className="mt-3 space-y-2">{group.items.map((item) => <button key={item} type="button" onClick={() => setSelectedType(item)} className={"flex w-full items-center gap-3 rounded-xl border px-3 py-3 text-left text-xs font-extrabold transition " + (selectedType === item ? "border-[#1f6a58] bg-[#e8f6ee] text-[#1f6a58]" : "border-[#e1ebe6] bg-[#fbfdfb] text-[#06201c] hover:border-[#b7d5c8]")}><TypeIcon type={item} /><span>{item}</span></button>)}</div></div>)}</div><div className="mt-6 rounded-2xl border border-[#e1ebe6] bg-[#f9fcfa] p-4"><p className="text-sm font-extrabold text-[#06201c]">{selectedType}</p><p className="mt-1 text-xs leading-5 text-[#52736a]">{selectedTypeDescription}</p></div><div className="mt-6 flex justify-end"><button type="button" onClick={() => setAddStep("settings")} className="h-11 rounded-full bg-[#1f6a58] px-5 text-sm font-extrabold text-white">Continue to settings</button></div></> : <AddLessonSettings selectedType={selectedType} onBack={() => setAddStep("type")} onAdd={addLesson} />}</ModalShell> : null}
      {editingLesson && draftLesson ? <ModalShell title="Edit lesson" eyebrow="Lesson settings" onClose={() => { setEditingLesson(null); setDraftLesson(null); }}><LessonSettingsForm lesson={draftLesson} setLesson={setDraftLesson} onCancel={() => { setEditingLesson(null); setDraftLesson(null); }} onSave={saveLesson} /></ModalShell> : null}
      {isPublishReviewOpen ? <PublishReviewModal lessons={lessons} onCancel={() => setIsPublishReviewOpen(false)} onPublish={publishCourse} /> : null}
      {isCourseSettingsOpen ? <ModalShell title="Learner experience" eyebrow="Course settings" onClose={() => setIsCourseSettingsOpen(false)}><p className="mt-2 text-sm text-[#52736a]">These capabilities apply across the course and its lessons.</p><div className="mt-5 rounded-2xl border border-[#e1ebe6] px-4"><ToggleRow label="Progress tracking" enabled={courseSettings.progressTracking} onToggle={() => toggleSetting("progressTracking")} /><ToggleRow label="Certificates" enabled={courseSettings.certificates} onToggle={() => toggleSetting("certificates")} /><ToggleRow label="Attendance summaries" enabled={courseSettings.attendance} onToggle={() => toggleSetting("attendance")} /><ToggleRow label="Course expiry" enabled={courseSettings.expiry} onToggle={() => toggleSetting("expiry")} /><ToggleRow label="Instructor reporting" enabled={courseSettings.reporting} onToggle={() => toggleSetting("reporting")} /></div><button type="button" onClick={() => setIsCourseSettingsOpen(false)} className="mt-6 h-11 w-full rounded-full bg-[#1f6a58] text-sm font-extrabold text-white">Done</button></ModalShell> : null}
    </div>
  );
}

type TypeField = { label: string; placeholder?: string; options?: string[] };
function getLessonPublishingIssues(lesson: Lesson): string[] {
  const issues: string[] = [];
  if (!lesson.title.trim()) issues.push("needs a title");
  if (!lesson.description.trim()) issues.push("needs learner instructions");
  if (lesson.typeSettings === "Not configured" || !lesson.typeSettings.trim()) issues.push("needs type-specific content");
  if (["Formal Assessment", "Quiz"].includes(lesson.type) && lesson.completionRule === "Mark as complete") issues.push("needs a result-based completion rule");
  if (["Assignment", "Practical Exercise"].includes(lesson.type) && lesson.completionRule === "Mark as complete") issues.push("needs a submission completion rule");
  return issues;
}

function PublishReviewModal({ lessons, onCancel, onPublish }: { lessons: Lesson[]; onCancel: () => void; onPublish: () => void }) {
  const issues = lessons.flatMap((lesson) => getLessonPublishingIssues(lesson).map((issue) => `${lesson.title || lesson.type} ${issue}`));
  return <ModalShell title="Review before publishing" eyebrow="Admin publishing checklist" onClose={onCancel}><p className="mt-2 text-sm text-[#52736a]">Review the course setup before making it available to learners.</p><div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-[#f9fcfa] p-4"><p className="text-[10px] font-extrabold uppercase tracking-wide text-[#7f9d94]">Lessons</p><p className="mt-1 text-2xl font-extrabold text-[#06201c]">{lessons.length}</p></div><div className="rounded-2xl bg-[#f9fcfa] p-4"><p className="text-[10px] font-extrabold uppercase tracking-wide text-[#7f9d94]">Required</p><p className="mt-1 text-2xl font-extrabold text-[#06201c]">{lessons.filter((lesson) => lesson.required).length}</p></div><div className="rounded-2xl bg-[#f9fcfa] p-4"><p className="text-[10px] font-extrabold uppercase tracking-wide text-[#7f9d94]">Ready</p><p className="mt-1 text-2xl font-extrabold text-[#1f6a58]">{issues.length === 0 ? "Yes" : "Review"}</p></div></div><div className="mt-5 rounded-2xl border border-[#e1ebe6] p-4"><p className="text-xs font-extrabold text-[#06201c]">Lesson checklist</p><div className="mt-3 space-y-2">{lessons.map((lesson) => <div key={lesson.id} className="flex items-center justify-between gap-3 rounded-xl bg-[#f9fcfa] px-3 py-2 text-xs"><span className="font-semibold text-[#52736a]">{lesson.title}</span><span className={lesson.status === "Published" ? "font-extrabold text-[#1f6a58]" : "font-extrabold text-[#8a5a00]"}>{lesson.status}</span></div>)}</div>{issues.length > 0 ? <div className="mt-4 rounded-xl bg-[#fff4f2] px-3 py-3 text-xs font-semibold leading-5 text-[#b42318]"><p className="font-extrabold">Needs attention</p>{issues.map((issue) => <p key={issue}>- {issue}</p>)}</div> : <p className="mt-4 rounded-xl bg-[#effaf4] px-3 py-3 text-xs font-semibold text-[#167550]">All required publishing checks are complete.</p>}</div><div className="mt-6 flex justify-end gap-3"><button type="button" onClick={onCancel} className="h-11 rounded-full border border-[#d7e5df] px-5 text-sm font-bold text-[#52736a]">Back to builder</button><button type="button" disabled={issues.length > 0} onClick={onPublish} className="h-11 rounded-full bg-[#1f6a58] px-5 text-sm font-extrabold text-white disabled:cursor-not-allowed disabled:opacity-40">Confirm publish</button></div></ModalShell>;
}

type EbookBlock = { id: number; kind: "Text" | "Image" | "Video" | "Audio" | "PDF" | "Resource link"; title: string; fileName?: string; content?: string };

function EbookBuilder({ onChange }: { onChange: (value: string) => void }) {
  const [chapters, setChapters] = useState<Array<{ id: number; title: string; blocks: EbookBlock[] }>>([{ id: 1, title: "Chapter 1", blocks: [{ id: 1, kind: "Text", title: "Introduction" }] }]);
  const [activeChapterId, setActiveChapterId] = useState(1);
  const [blockType, setBlockType] = useState<EbookBlock["kind"]>("Text");
  const [editingBlock, setEditingBlock] = useState<EbookBlock | null>(null);
  const activeChapter = chapters.find((chapter) => chapter.id === activeChapterId) ?? chapters[0];
  const sync = (nextChapters: typeof chapters) => { setChapters(nextChapters); onChange(nextChapters.map((chapter) => chapter.title + ": " + chapter.blocks.map((block) => block.kind).join(", ")).join(" | ")); };
  const addChapter = () => { const id = Date.now(); sync([...chapters, { id, title: "New chapter", blocks: [] }]); setActiveChapterId(id); };
  const addBlock = () => { const block: EbookBlock = { id: Date.now(), kind: blockType, title: "New " + blockType + " block" }; sync(chapters.map((chapter) => chapter.id === activeChapter.id ? { ...chapter, blocks: [...chapter.blocks, block] } : chapter)); setEditingBlock(block); };
  const removeBlock = (blockId: number) => sync(chapters.map((chapter) => chapter.id === activeChapter.id ? { ...chapter, blocks: chapter.blocks.filter((block) => block.id !== blockId) } : chapter));
  const saveBlock = () => { if (!editingBlock) return; sync(chapters.map((chapter) => chapter.id === activeChapter.id ? { ...chapter, blocks: chapter.blocks.map((block) => block.id === editingBlock.id ? editingBlock : block) } : chapter)); setEditingBlock(null); };

  return (
    <div className="mb-5 rounded-2xl border border-[#b7d5c8] bg-[#f4fbf6] p-4">
      <div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-extrabold text-[#06201c]">eBook authoring canvas</p><p className="mt-1 max-w-xl text-xs leading-5 text-[#52736a]">Create chapters and place any supported content block on any page in the reading experience.</p></div><button type="button" onClick={addChapter} className="rounded-full border border-[#b7d5c8] px-3 py-2 text-xs font-extrabold text-[#1f6a58] hover:bg-white">+ Add chapter</button></div>
      <div className="mt-4 grid gap-4 lg:grid-cols-[190px_minmax(0,1fr)]">
        <div className="space-y-2 rounded-xl border border-[#d7e5df] bg-white p-2">{chapters.map((chapter, index) => <button key={chapter.id} type="button" onClick={() => setActiveChapterId(chapter.id)} className={"flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-xs font-extrabold " + (activeChapter.id === chapter.id ? "bg-[#e8f6ee] text-[#1f6a58]" : "text-[#52736a] hover:bg-[#f4faf7]")}><span>{index + 1}. {chapter.title}</span><span>{chapter.blocks.length}</span></button>)}</div>
        <div className="rounded-xl border border-[#d7e5df] bg-white p-4">
          <div className="flex flex-wrap items-center justify-between gap-3"><div><input aria-label="Chapter title" value={activeChapter.title} onChange={(event) => sync(chapters.map((chapter) => chapter.id === activeChapter.id ? { ...chapter, title: event.target.value } : chapter))} className="h-9 rounded-lg border border-transparent bg-transparent px-2 text-sm font-extrabold text-[#06201c] outline-none focus:border-[#d7e5df] focus:bg-white" /><p className="mt-1 text-xs text-[#7f9d94]">Page canvas - add content in any order</p></div><div className="flex w-full gap-2 sm:w-auto"><select value={blockType} onChange={(event) => setBlockType(event.target.value as EbookBlock["kind"])} className="h-9 min-w-0 flex-1 rounded-lg border border-[#d7e5df] bg-white px-2 text-xs font-semibold text-[#06201c] sm:flex-none"><option>Text</option><option>Image</option><option>Video</option><option>Audio</option><option>PDF</option><option>Resource link</option></select><button type="button" onClick={addBlock} className="h-9 shrink-0 rounded-lg bg-[#1f6a58] px-3 text-xs font-extrabold text-white">+ Add block</button></div></div>
          <div className="mt-4 space-y-2">{activeChapter.blocks.length === 0 ? <div className="rounded-xl border border-dashed border-[#b7d5c8] px-4 py-8 text-center text-xs text-[#7f9d94]">This page is empty. Add text, media, a PDF, or a resource link.</div> : activeChapter.blocks.map((block) => <div key={block.id} className="flex items-center gap-3 rounded-xl border border-[#e1ebe6] bg-[#fbfdfb] p-3"><TypeIcon type={block.kind} /><div className="min-w-0 flex-1"><p className="text-xs font-extrabold text-[#06201c]">{block.title}</p><p className="mt-1 text-[11px] text-[#52736a]">{block.kind}{block.fileName ? " - " + block.fileName : " - ready to configure"}</p></div><button type="button" onClick={() => setEditingBlock({ ...block })} className="rounded-lg border border-[#d7e5df] px-2 py-1 text-[11px] font-bold text-[#1f6a58] hover:bg-[#e8f6ee]">Configure</button><button type="button" onClick={() => removeBlock(block.id)} className="rounded-lg px-2 py-1 text-xs font-bold text-[#b42318] hover:bg-[#fff2f0]">Remove</button></div>)}</div>
          {editingBlock ? <div className="mt-4 rounded-2xl border border-[#1f6a58] bg-white p-4"><p className="text-xs font-extrabold text-[#06201c]">Configure {editingBlock.kind} block</p><div className="mt-3 space-y-3"><Field label="Block title" value={editingBlock.title} onChange={(title) => setEditingBlock({ ...editingBlock, title })} />{editingBlock.kind === "Text" ? <label className="block text-xs font-extrabold text-[#52736a]">Page content<textarea value={editingBlock.content ?? ""} onChange={(event) => setEditingBlock({ ...editingBlock, content: event.target.value })} placeholder="Write learner-facing content..." className="mt-2 min-h-32 w-full rounded-xl border border-[#d7e5df] p-3 text-sm text-[#06201c]" /></label> : <><Field label={editingBlock.kind === "Resource link" ? "Resource URL" : "Content description"} value={editingBlock.content ?? ""} onChange={(content) => setEditingBlock({ ...editingBlock, content })} placeholder={editingBlock.kind === "Resource link" ? "https://..." : "Describe this content"} />{editingBlock.kind !== "Resource link" ? <label className="inline-flex cursor-pointer items-center rounded-full bg-[#1f6a58] px-4 py-2 text-xs font-extrabold text-white">{editingBlock.fileName ? "Replace file" : "Upload file"}<input type="file" className="sr-only" onChange={(event) => { const file = event.target.files?.[0]; if (file) setEditingBlock({ ...editingBlock, fileName: file.name }); }} /></label> : null}</>}</div><div className="mt-4 flex justify-end gap-2"><button type="button" onClick={() => setEditingBlock(null)} className="rounded-full border border-[#d7e5df] px-4 py-2 text-xs font-bold text-[#52736a]">Cancel</button><button type="button" onClick={saveBlock} className="rounded-full bg-[#1f6a58] px-4 py-2 text-xs font-extrabold text-white">Save block</button></div></div> : null}
        </div>
      </div>
    </div>
  );
}

function AdminContentBlock({ type, value, onChange }: { type: string; value: string; onChange: (value: string) => void }) {
  void value;
  const [fileName, setFileName] = useState("");
  const [content, setContent] = useState("");
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [imageName, setImageName] = useState("");
  const [showLinkEditor, setShowLinkEditor] = useState(false);
  const [linkText, setLinkText] = useState("");
  const [linkUrl, setLinkUrl] = useState("");
  const [questionCount, setQuestionCount] = useState(1);
  const isFileContent = ["Video", "Audio", "eBook", "PDF and Resources"].includes(type);
  const isWrittenContent = type === "Reading / Topic" || type === "Case Study / Scenario";
  const isAssessment = type === "Quiz" || type === "Formal Assessment";
  const isSubmission = type === "Assignment" || type === "Practical Exercise";
  const isSession = type === "Live Session" || type === "In-person Session";
  const selectFile = (file: File | undefined) => { if (!file) return; setFileName(file.name); onChange(file.name); };
  if (isFileContent) return <div className="mb-5 rounded-2xl border border-dashed border-[#9fcab5] bg-[#f4fbf6] p-4"><div className="flex items-start gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e8f6ee] text-xs font-extrabold text-[#1f6a58]">{type === "PDF and Resources" ? "PDF" : "FILE"}</span><div className="flex-1"><p className="text-sm font-extrabold text-[#06201c]">Add {type.toLowerCase()} content</p><p className="mt-1 text-xs leading-5 text-[#52736a]">Upload the learner-facing file or choose one already available in your library.</p><label className="mt-3 inline-flex h-10 cursor-pointer items-center rounded-full bg-[#1f6a58] px-4 text-xs font-extrabold text-white">{fileName ? "Replace file" : "Choose file"}<input type="file" className="sr-only" accept={type === "Video" ? "video/*" : type === "Audio" ? "audio/*" : type === "eBook" ? ".epub,.pdf" : ".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx"} onChange={(event) => selectFile(event.target.files?.[0])} /></label>{fileName ? <span className="ml-3 text-xs font-semibold text-[#1f6a58]">{fileName}</span> : null}</div></div></div>;
  if (isWrittenContent) return <div className="mb-5 rounded-2xl border border-[#d7e5df] bg-white p-4"><div className="flex items-center justify-between"><p className="text-xs font-extrabold text-[#06201c]">Content editor</p><span className="text-[10px] font-bold text-[#7f9d94]">Learner-facing</span></div><div className="mt-3 flex gap-1 rounded-t-xl border border-b-0 border-[#d7e5df] bg-[#f7fbf8] p-2"><button type="button" className="rounded px-2 py-1 text-xs font-bold text-[#52736a] hover:bg-white">B</button><button type="button" className="rounded px-2 py-1 text-xs italic text-[#52736a] hover:bg-white">I</button><button type="button" onClick={() => setShowLinkEditor((current) => !current)} className="rounded px-2 py-1 text-xs font-bold text-[#52736a] hover:bg-white">Link</button><button type="button" onClick={() => imageInputRef.current?.click()} className="rounded px-2 py-1 text-xs font-bold text-[#52736a] hover:bg-white">Image</button><input ref={imageInputRef} type="file" accept="image/*" className="sr-only" onChange={(event) => { const file = event.target.files?.[0]; if (!file) return; setImageName(file.name); const nextContent = content ? content + "\n[Image: " + file.name + "]" : "[Image: " + file.name + "]"; setContent(nextContent); onChange(nextContent); }} /></div>{showLinkEditor ? <div className="mt-3 grid gap-2 rounded-xl border border-[#d7e5df] bg-[#f9fcfa] p-3 sm:grid-cols-2"><input value={linkText} onChange={(event) => setLinkText(event.target.value)} placeholder="Link text" className="h-10 rounded-lg border border-[#d7e5df] bg-white px-3 text-xs text-[#06201c]" /><input value={linkUrl} onChange={(event) => setLinkUrl(event.target.value)} placeholder="https://..." className="h-10 rounded-lg border border-[#d7e5df] bg-white px-3 text-xs text-[#06201c]" /><div className="flex gap-2 sm:col-span-2"><button type="button" onClick={() => { if (!linkUrl.trim()) return; const nextContent = content ? content + "\n[" + (linkText.trim() || linkUrl.trim()) + "](" + linkUrl.trim() + ")" : "[" + (linkText.trim() || linkUrl.trim()) + "](" + linkUrl.trim() + ")"; setContent(nextContent); onChange(nextContent); setShowLinkEditor(false); setLinkText(""); setLinkUrl(""); }} className="rounded-full bg-[#1f6a58] px-3 py-2 text-xs font-extrabold text-white">Insert link</button><button type="button" onClick={() => setShowLinkEditor(false)} className="rounded-full border border-[#d7e5df] px-3 py-2 text-xs font-bold text-[#52736a]">Cancel</button></div></div> : null}<textarea value={content} onChange={(event) => { setContent(event.target.value); onChange(event.target.value); }} placeholder="Write the content learners will see..." className="min-h-32 w-full resize-y rounded-b-xl border border-[#d7e5df] p-3 text-sm text-[#06201c] outline-none focus:border-[#1f6a58]" />{imageName ? <p className="mt-2 rounded-lg bg-[#effaf4] px-3 py-2 text-xs font-semibold text-[#167550]">Image attached: {imageName}</p> : null}</div>;
  if (isAssessment) return type === "Formal Assessment" ? <FormalAssessmentBuilder onChange={onChange} /> : <QuizBuilder onChange={onChange} questionCount={questionCount} setQuestionCount={setQuestionCount} />;
  if (type === "Survey / Feedback") return <SurveyBuilder onChange={onChange} />;
  if (type === "Discussion / Q&A") return <DiscussionBuilder onChange={onChange} />;
  if (isSubmission) return <div className="mb-5 rounded-2xl border border-[#d7e5df] bg-white p-4"><p className="text-xs font-extrabold text-[#06201c]">Learner submission setup</p><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="flex items-center gap-3 rounded-xl border border-[#e1ebe6] p-3 text-xs font-semibold text-[#52736a]"><input type="checkbox" defaultChecked className="h-4 w-4 accent-[#1f6a58]" /> Allow file uploads</label><label className="flex items-center gap-3 rounded-xl border border-[#e1ebe6] p-3 text-xs font-semibold text-[#52736a]"><input type="checkbox" defaultChecked className="h-4 w-4 accent-[#1f6a58]" /> Require instructor review</label></div><p className="mt-3 text-xs leading-5 text-[#52736a]">Learners will see submission instructions, deadline, upload action, and feedback status.</p></div>;
  if (isSession) return <div className="mb-5 rounded-2xl border border-[#d7e5df] bg-white p-4"><div className="flex items-center justify-between"><div><p className="text-xs font-extrabold text-[#06201c]">Session details</p><p className="mt-1 text-xs text-[#52736a]">These details appear on the learner calendar and session card.</p></div><span className="rounded-full bg-[#fff8e1] px-3 py-1 text-[10px] font-extrabold text-[#8a5a00]">Attendance</span></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-[#f9fcfa] p-3 text-xs font-semibold text-[#52736a]">Schedule<br /><span className="font-extrabold text-[#06201c]">Date and time</span></div><div className="rounded-xl bg-[#f9fcfa] p-3 text-xs font-semibold text-[#52736a]">{type === "Live Session" ? "Join" : "Location"}<br /><span className="font-extrabold text-[#06201c]">{type === "Live Session" ? "Meeting link" : "Venue details"}</span></div><div className="rounded-xl bg-[#f9fcfa] p-3 text-xs font-semibold text-[#52736a]">Tracking<br /><span className="font-extrabold text-[#06201c]">Attendance rule</span></div></div></div>;
  return null;
}

function BuilderActions({ onStatus }: { onStatus: (status: string) => void }) {
  const [previewing, setPreviewing] = useState(false);
  return <><div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-[#e1ebe6] pt-4"><span className="text-[11px] font-semibold text-[#7f9d94]">Changes are saved locally until the lesson is saved.</span><div className="flex flex-wrap gap-2"><button type="button" onClick={() => onStatus("Draft saved") } className="rounded-full border border-[#b7d5c8] px-3 py-2 text-xs font-extrabold text-[#1f6a58]">Save draft</button><button type="button" onClick={() => setPreviewing((current) => !current)} className="rounded-full border border-[#d7e5df] px-3 py-2 text-xs font-extrabold text-[#52736a]">{previewing ? "Close preview" : "Preview as learner"}</button><button type="button" onClick={() => onStatus("Ready to publish - save the lesson to apply this status")} className="rounded-full bg-[#1f6a58] px-3 py-2 text-xs font-extrabold text-white">Publish</button></div></div>{previewing ? <div className="mt-3 rounded-xl border border-[#bce8d1] bg-[#effaf4] p-3"><p className="text-xs font-extrabold text-[#167550]">Learner preview</p><p className="mt-1 text-xs leading-5 text-[#52736a]">This is the learner-facing experience for the current configuration. Save the lesson when you are ready.</p></div> : null}</>;
}

function QuizBuilder({ onChange, questionCount, setQuestionCount }: { onChange: (value: string) => void; questionCount: number; setQuestionCount: (value: number | ((value: number) => number)) => void }) {
  const [questionType, setQuestionType] = useState("Multiple choice");
  const [passScore, setPassScore] = useState("80%");
  const [attempts, setAttempts] = useState("3 attempts");
  const [status, setStatus] = useState("");
  const sync = (next: string) => { onChange(next); };
  return <div className="mb-5 rounded-2xl border border-[#d7e5df] bg-white p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-extrabold text-[#06201c]">Question builder</p><p className="mt-1 text-xs text-[#52736a]">Create questions, then define scoring and attempts.</p></div><span className="rounded-full bg-[#e8f6ee] px-3 py-1 text-xs font-extrabold text-[#1f6a58]">{questionCount} question{questionCount === 1 ? "" : "s"}</span></div><div className="mt-4 rounded-xl border border-[#e1ebe6] bg-[#f9fcfa] p-3"><input placeholder="Write your question..." onChange={(event) => sync(event.target.value)} className="h-10 w-full rounded-lg border border-[#d7e5df] bg-white px-3 text-xs text-[#06201c]" /><div className="mt-3 grid gap-3 sm:grid-cols-3"><select value={questionType} onChange={(event) => setQuestionType(event.target.value)} className="h-10 rounded-lg border border-[#d7e5df] bg-white px-2 text-xs font-semibold text-[#06201c]"><option>Multiple choice</option><option>True / false</option><option>Short answer</option></select><input value={passScore} onChange={(event) => setPassScore(event.target.value)} placeholder="Pass score" className="h-10 rounded-lg border border-[#d7e5df] bg-white px-3 text-xs text-[#06201c]" /><select value={attempts} onChange={(event) => setAttempts(event.target.value)} className="h-10 rounded-lg border border-[#d7e5df] bg-white px-2 text-xs font-semibold text-[#06201c]"><option>1 attempt</option><option>3 attempts</option><option>Unlimited attempts</option></select></div><p className="mt-2 text-[11px] text-[#7f9d94]">For multiple choice questions, add answer options and mark the correct answer before publishing.</p></div><button type="button" onClick={() => setQuestionCount((count) => count + 1)} className="mt-3 rounded-full border border-[#b7d5c8] px-4 py-2 text-xs font-extrabold text-[#1f6a58]">+ Add question</button><BuilderActions onStatus={setStatus} />{status ? <p className="mt-2 text-xs font-bold text-[#167550]">{status}</p> : null}</div>;
}

function FormalAssessmentBuilder({ onChange }: { onChange: (value: string) => void }) {
  const [sections, setSections] = useState(["Section 1"]);
  const [questions, setQuestions] = useState(1);
  const [timeLimit, setTimeLimit] = useState("60 minutes");
  const [attempts, setAttempts] = useState("1 attempt");
  const [grading, setGrading] = useState("Manual grading");
  const [passScore, setPassScore] = useState("70%");
  const [feedback, setFeedback] = useState("Release after grading");
  const [status, setStatus] = useState("");
  const sync = (nextSections = sections) => onChange(`${nextSections.join(", ")} · ${questions} questions · ${timeLimit} · ${attempts} · ${grading} · pass ${passScore} · ${feedback}`);
  return <div className="mb-5 rounded-2xl border border-[#d7e5df] bg-white p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-extrabold text-[#06201c]">Assessment builder</p><p className="mt-1 text-xs text-[#52736a]">Set up the assessment in the same order an admin creates it.</p></div><span className="rounded-full bg-[#fff8e1] px-3 py-1 text-[10px] font-extrabold text-[#8a5a00]">{sections.length} section{sections.length === 1 ? "" : "s"}</span></div><div className="mt-4 space-y-2">{sections.map((section, index) => <div key={section + index} className="flex items-center gap-2 rounded-xl border border-[#e1ebe6] bg-[#f9fcfa] p-3"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-[#e8f6ee] text-xs font-extrabold text-[#1f6a58]">{index + 1}</span><input value={section} onChange={(event) => { const next = sections.map((item, itemIndex) => itemIndex === index ? event.target.value : item); setSections(next); sync(next); }} className="h-9 min-w-0 flex-1 rounded-lg border border-[#d7e5df] bg-white px-3 text-xs font-semibold text-[#06201c]" /><button type="button" onClick={() => setQuestions((count) => count + 1)} className="rounded-lg border border-[#d7e5df] px-2 py-2 text-[11px] font-bold text-[#1f6a58]">+ Question</button></div>)}</div><button type="button" onClick={() => { const next = [...sections, `Section ${sections.length + 1}`]; setSections(next); sync(next); }} className="mt-3 rounded-full border border-[#b7d5c8] px-4 py-2 text-xs font-extrabold text-[#1f6a58]">+ Add section</button><p className="mt-3 text-xs font-bold text-[#52736a]">{questions} question{questions === 1 ? "" : "s"} across this assessment</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><Field label="Time limit" value={timeLimit} onChange={(value) => { setTimeLimit(value); sync(); }} placeholder="For example, 60 minutes" /><Field label="Passing score" value={passScore} onChange={(value) => { setPassScore(value); sync(); }} placeholder="For example, 70%" /><label className="block text-xs font-extrabold text-[#52736a]">Attempt rules<select value={attempts} onChange={(event) => { setAttempts(event.target.value); sync(); }} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 text-sm font-semibold text-[#06201c]"><option>1 attempt</option><option>2 attempts</option><option>Unlimited attempts</option></select></label><label className="block text-xs font-extrabold text-[#52736a]">Grading method<select value={grading} onChange={(event) => { setGrading(event.target.value); sync(); }} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 text-sm font-semibold text-[#06201c]"><option>Manual grading</option><option>Automatic grading</option><option>Mixed grading</option></select></label><label className="block text-xs font-extrabold text-[#52736a] sm:col-span-2">Feedback release<select value={feedback} onChange={(event) => { setFeedback(event.target.value); sync(); }} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 text-sm font-semibold text-[#06201c]"><option>Release after grading</option><option>Release immediately</option><option>Release on a date</option></select></label></div><label className="mt-3 flex items-center gap-3 rounded-xl border border-[#e1ebe6] p-3 text-xs font-semibold text-[#52736a]"><input type="checkbox" className="h-4 w-4 accent-[#1f6a58]" /> Require proctoring or identity check</label><BuilderActions onStatus={setStatus} />{status ? <p className="mt-2 text-xs font-bold text-[#167550]">{status}</p> : null}</div>;
}

function SurveyBuilder({ onChange }: { onChange: (value: string) => void }) {
  const [questions, setQuestions] = useState([{ label: "How satisfied are you?", type: "Rating", required: true }]);
  const [privacy, setPrivacy] = useState("Named responses");
  const [confirmation, setConfirmation] = useState("Thank you for your feedback.");
  const [status, setStatus] = useState("");
  const sync = (next = questions) => onChange(`${next.length} questions · ${privacy} · ${confirmation}`);
  return <div className="mb-5 rounded-2xl border border-[#d7e5df] bg-white p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-extrabold text-[#06201c]">Survey builder</p><p className="mt-1 text-xs text-[#52736a]">Create a clear response flow with privacy and confirmation controls.</p></div><span className="rounded-full bg-[#e8f6ee] px-3 py-1 text-xs font-extrabold text-[#1f6a58]">{questions.length} question{questions.length === 1 ? "" : "s"}</span></div><div className="mt-4 space-y-2">{questions.map((question, index) => <div key={index} className="rounded-xl border border-[#e1ebe6] bg-[#f9fcfa] p-3"><div className="flex flex-wrap items-center gap-2"><input value={question.label} onChange={(event) => { const next = questions.map((item, itemIndex) => itemIndex === index ? { ...item, label: event.target.value } : item); setQuestions(next); sync(next); }} className="h-10 min-w-0 flex-1 rounded-lg border border-[#d7e5df] bg-white px-3 text-xs font-semibold text-[#06201c]" /><select value={question.type} onChange={(event) => { const next = questions.map((item, itemIndex) => itemIndex === index ? { ...item, type: event.target.value } : item); setQuestions(next); sync(next); }} className="h-10 rounded-lg border border-[#d7e5df] bg-white px-2 text-xs font-semibold text-[#06201c]"><option>Rating</option><option>Text response</option><option>Multiple choice</option><option>Scale</option></select></div><label className="mt-2 inline-flex items-center gap-2 text-[11px] font-bold text-[#52736a]"><input type="checkbox" checked={question.required} onChange={(event) => { const next = questions.map((item, itemIndex) => itemIndex === index ? { ...item, required: event.target.checked } : item); setQuestions(next); sync(next); }} className="h-4 w-4 accent-[#1f6a58]" /> Required question</label></div>)}</div><button type="button" onClick={() => { const next = [...questions, { label: "New question", type: "Text response", required: false }]; setQuestions(next); sync(next); }} className="mt-3 rounded-full border border-[#b7d5c8] px-4 py-2 text-xs font-extrabold text-[#1f6a58]">+ Add question</button><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="block text-xs font-extrabold text-[#52736a]">Response privacy<select value={privacy} onChange={(event) => { setPrivacy(event.target.value); sync(); }} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 text-sm font-semibold text-[#06201c]"><option>Named responses</option><option>Anonymous responses</option></select></label><Field label="Submission confirmation" value={confirmation} onChange={(value) => { setConfirmation(value); sync(); }} placeholder="Thank-you message" /></div><BuilderActions onStatus={setStatus} />{status ? <p className="mt-2 text-xs font-bold text-[#167550]">{status}</p> : null}</div>;
}

function DiscussionBuilder({ onChange }: { onChange: (value: string) => void }) {
  const [prompt, setPrompt] = useState("");
  const [mode, setMode] = useState("Participation mode");
  const [requirePost, setRequirePost] = useState(true);
  const [requireReply, setRequireReply] = useState(false);
  const [moderation, setModeration] = useState("Instructor moderation");
  const [dueDate, setDueDate] = useState("");
  const [status, setStatus] = useState("");
  const sync = (nextPrompt = prompt) => onChange(`${nextPrompt} · ${mode} · ${requirePost ? "one post" : "no post requirement"} · ${requireReply ? "replies required" : "replies optional"} · ${moderation} · ${dueDate}`);
  return <div className="mb-5 rounded-2xl border border-[#d7e5df] bg-white p-4"><div><p className="text-xs font-extrabold text-[#06201c]">Discussion builder</p><p className="mt-1 text-xs text-[#52736a]">Define the prompt, participation expectations, and moderation workflow.</p></div><label className="mt-4 block text-xs font-extrabold text-[#52736a]">Discussion prompt<textarea value={prompt} onChange={(event) => { setPrompt(event.target.value); sync(event.target.value); }} placeholder="What should learners discuss?" className="mt-2 min-h-24 w-full rounded-xl border border-[#d7e5df] p-3 text-sm text-[#06201c]" /></label><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="block text-xs font-extrabold text-[#52736a]">Participation mode<select value={mode} onChange={(event) => { setMode(event.target.value); sync(); }} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 text-sm font-semibold text-[#06201c]"><option>Participation mode</option><option>Read-only</option><option>Post and reply</option></select></label><Field label="Due date" value={dueDate} onChange={(value) => { setDueDate(value); sync(); }} placeholder="Choose deadline" /><label className="flex items-center gap-3 rounded-xl border border-[#e1ebe6] p-3 text-xs font-semibold text-[#52736a]"><input type="checkbox" checked={requirePost} onChange={(event) => { setRequirePost(event.target.checked); sync(); }} className="h-4 w-4 accent-[#1f6a58]" /> Require one post</label><label className="flex items-center gap-3 rounded-xl border border-[#e1ebe6] p-3 text-xs font-semibold text-[#52736a]"><input type="checkbox" checked={requireReply} onChange={(event) => { setRequireReply(event.target.checked); sync(); }} className="h-4 w-4 accent-[#1f6a58]" /> Require replies to others</label><label className="block text-xs font-extrabold text-[#52736a] sm:col-span-2">Moderation<select value={moderation} onChange={(event) => { setModeration(event.target.value); sync(); }} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 text-sm font-semibold text-[#06201c]"><option>Instructor moderation</option><option>Post immediately</option><option>Review reported posts</option></select></label></div><BuilderActions onStatus={setStatus} />{status ? <p className="mt-2 text-xs font-bold text-[#167550]">{status}</p> : null}</div>;
}

function getTypeFields(type: string): TypeField[] {
  if (type === "Reading / Topic") return [{ label: "Content editor", placeholder: "Write or paste lesson content" }, { label: "Supporting materials", placeholder: "Images, links, or attachments" }, { label: "Reading completion", options: ["Read to the end", "Time spent", "Mark manually"] }];
  if (type === "eBook") return [{ label: "eBook source", placeholder: "Upload EPUB or add chapters" }, { label: "Chapter structure", placeholder: "Chapter count and reading order" }, { label: "Reading progress", options: ["Finish all chapters", "Read percentage", "Mark manually"] }];
  if (type === "Video") return [{ label: "Video URL or file", placeholder: "Upload video or paste URL" }, { label: "Captions and transcript", placeholder: "Upload captions or transcript" }, { label: "Watch completion", options: ["Watch to the end", "Watch 80%", "Mark manually"] }];
  if (type === "Audio") return [{ label: "Audio file or URL", placeholder: "Upload audio or paste URL" }, { label: "Transcript", placeholder: "Upload or paste transcript" }, { label: "Listen completion", options: ["Listen to the end", "Listen 80%", "Mark manually"] }];
  if (type === "PDF and Resources") return [{ label: "Files and resources", placeholder: "Upload PDFs or supporting files" }, { label: "Download permission", options: ["Open only", "Download allowed"] }, { label: "Resource completion", options: ["Open resource", "Download resource", "Mark manually"] }];
  if (type === "External Link") return [{ label: "External URL", placeholder: "https://..." }, { label: "Open behavior", options: ["Open in new tab", "Open in same tab"] }, { label: "Link completion", options: ["Open link", "Mark manually"] }];
  if (type === "Live Session") return [{ label: "Date, time, and timezone", placeholder: "Choose session schedule" }, { label: "Meeting link", placeholder: "https://meeting..." }, { label: "Attendance rule", options: ["Track attendance", "Mark manually"] }];
  if (type === "In-person Session") return [{ label: "Date, time, and timezone", placeholder: "Choose session schedule" }, { label: "Location and directions", placeholder: "Building, room, and map link" }, { label: "Attendance rule", options: ["Track attendance", "Mark manually"] }];
  if (type === "Case Study / Scenario") return [{ label: "Scenario content", placeholder: "Write the case or scenario" }, { label: "Response format", options: ["Text response", "Multiple choice", "File upload"] }, { label: "Review mode", options: ["Instructor review", "Automatic feedback", "No review"] }];
  if (type === "Practical Exercise") return [{ label: "Exercise steps", placeholder: "Add instructions and checklist" }, { label: "Evidence submission", options: ["No evidence", "File upload", "Photo or link"] }, { label: "Review mode", options: ["Instructor review", "Mark manually"] }];
  if (type === "Assignment") return [{ label: "Due date", placeholder: "Choose deadline" }, { label: "Submission type", options: ["Text", "File upload", "Link"] }, { label: "Grading", options: ["Manual grading", "Rubric", "Pass / fail"] }];
  if (type === "Quiz") return [{ label: "Questions", placeholder: "Add or select questions" }, { label: "Pass score", placeholder: "For example, 80%" }, { label: "Attempts and results", options: ["1 attempt", "3 attempts", "Unlimited attempts"] }];
  if (type === "Formal Assessment") return [{ label: "Assessment sections", placeholder: "Add sections and questions" }, { label: "Time limit", placeholder: "For example, 60 minutes" }, { label: "Results and feedback", options: ["Release immediately", "Release after review"] }];
  if (type === "Survey / Feedback") return [{ label: "Survey questions", placeholder: "Add rating, text, or scale questions" }, { label: "Response privacy", options: ["Named responses", "Anonymous responses"] }, { label: "Submission confirmation", placeholder: "Thank-you message" }];
  return [{ label: "Discussion prompt", placeholder: "Write the question or topic" }, { label: "Participation rule", options: ["Read only", "Post response", "Post and reply"] }, { label: "Moderation and due date", placeholder: "Moderation notes or deadline" }];
}

function TypeSettingsField({ type, value, onChange }: { type: string; value: string; onChange: (value: string) => void }) {
  if (type === "eBook") return <EbookBuilder onChange={onChange} />;
  const fields = getTypeFields(type);
  const [values, setValues] = useState<Record<string, string>>({ first: value });
  const update = (key: string, next: string) => { const updated = { ...values, [key]: next }; setValues(updated); onChange(fields.map((_, index) => updated[String(index)]).filter(Boolean).join("  |  ")); };
  return <><AdminContentBlock type={type} value={value} onChange={onChange} /><div className="grid gap-3 sm:grid-cols-2">{fields.map((field, index) => field.options ? <label key={field.label} className="block text-xs font-extrabold text-[#52736a]">{field.label}<select value={values[String(index)] ?? ""} onChange={(event) => update(String(index), event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 text-sm font-semibold text-[#06201c]"><option value="">Choose an option</option>{field.options.map((option) => <option key={option}>{option}</option>)}</select></label> : <Field key={field.label} label={field.label} value={values[String(index)] ?? (index === 0 ? value : "")} onChange={(next) => update(String(index), next)} placeholder={field.placeholder} />)}</div></>;
}

function LessonSettingsForm({ lesson, setLesson, onCancel, onSave }: { lesson: Lesson; setLesson: (lesson: Lesson) => void; onCancel: () => void; onSave: () => void }) {
  const update = (key: keyof Lesson, value: string | boolean) => setLesson({ ...lesson, [key]: value });
  return <><p className="mt-2 text-sm text-[#52736a]">Shared settings apply to every lesson. Type-specific options appear below.</p><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Lesson title" value={lesson.title} onChange={(value) => update("title", value)} /><Field label="Description / instructions" value={lesson.description} onChange={(value) => update("description", value)} placeholder="What should learners know?" /><label className="text-xs font-extrabold text-[#52736a]">Status<select value={lesson.status} onChange={(event) => update("status", event.target.value as LessonStatus)} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 py-2 text-sm font-semibold text-[#06201c]"><option>Draft</option><option>Published</option></select></label><Field label="Availability" value={lesson.availability} onChange={(value) => update("availability", value)} /><Field label="Prerequisite" value={lesson.prerequisite} onChange={(value) => update("prerequisite", value)} /><Field label="Completion rule" value={lesson.completionRule} onChange={(value) => update("completionRule", value)} /><label className="flex items-center gap-3 self-end rounded-xl border border-[#d7e5df] px-3 py-3 text-xs font-extrabold text-[#52736a]"><input type="checkbox" checked={lesson.required} onChange={(event) => update("required", event.target.checked)} className="h-4 w-4 accent-[#1f6a58]" /> Required lesson</label></div><div className="mt-5 rounded-2xl border border-[#e1ebe6] bg-[#f9fcfa] p-4"><p className="mb-3 text-xs font-extrabold text-[#06201c]">{lesson.type} settings</p><TypeSettingsField type={lesson.type} value={lesson.typeSettings} onChange={(value) => update("typeSettings", value)} /></div><div className="mt-6 flex justify-end gap-3"><button type="button" onClick={onCancel} className="h-11 rounded-full border border-[#d7e5df] px-5 text-sm font-bold text-[#52736a]">Cancel</button><button type="button" onClick={onSave} className="h-11 rounded-full bg-[#1f6a58] px-5 text-sm font-extrabold text-white">Save lesson</button></div></>;
}

function AddLessonSettings({ selectedType, onBack, onAdd }: { selectedType: string; onBack: () => void; onAdd: (details: Partial<Lesson>) => void }) {
  const [title, setTitle] = useState("New " + selectedType);
  const [description, setDescription] = useState("");
  const [status, setStatus] = useState<LessonStatus>("Draft");
  const [availability, setAvailability] = useState("Available immediately");
  const [prerequisite, setPrerequisite] = useState("None");
  const [completionRule, setCompletionRule] = useState("Mark as complete");
  const [typeSettings, setTypeSettings] = useState("Not configured");
  const [required, setRequired] = useState(true);
  const experience = selectedType === "Assignment" ? "Learners will submit work by a deadline and receive feedback." : selectedType === "Live Session" || selectedType === "In-person Session" ? "Learners will see schedule, joining details, and attendance status." : selectedType === "Quiz" || selectedType === "Formal Assessment" ? "Learners will answer questions and see results based on your rules." : "Learners will complete the content or action and their progress will be tracked.";
  return <><p className="mt-2 text-sm text-[#52736a]">Set the shared information now. You can refine the full lesson after saving.</p><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Lesson title" value={title} onChange={setTitle} /><Field label="Description / instructions" value={description} onChange={setDescription} placeholder="What should learners do?" /><label className="text-xs font-extrabold text-[#52736a]">Status<select value={status} onChange={(event) => setStatus(event.target.value as LessonStatus)} className="mt-2 h-11 w-full rounded-xl border border-[#d7e5df] bg-white px-3 text-sm font-semibold text-[#06201c]"><option>Draft</option><option>Published</option></select></label><Field label="Availability" value={availability} onChange={setAvailability} /><Field label="Prerequisite" value={prerequisite} onChange={setPrerequisite} /><Field label="Completion rule" value={completionRule} onChange={setCompletionRule} /><label className="flex items-center gap-3 self-end rounded-xl border border-[#d7e5df] px-3 py-3 text-xs font-extrabold text-[#52736a]"><input type="checkbox" checked={required} onChange={(event) => setRequired(event.target.checked)} className="h-4 w-4 accent-[#1f6a58]" /> Required lesson</label></div><div className="mt-5 rounded-2xl border border-[#bce8d1] bg-[#effaf4] p-4"><p className="mb-3 text-xs font-extrabold text-[#167550]">{selectedType} learner experience</p><p className="mb-4 text-xs leading-5 text-[#167550]">{experience}</p><TypeSettingsField type={selectedType} value={typeSettings} onChange={setTypeSettings} /></div><div className="mt-6 flex justify-between gap-3"><button type="button" onClick={onBack} className="h-11 rounded-full border border-[#d7e5df] px-5 text-sm font-bold text-[#52736a]">Back</button><button type="button" onClick={() => onAdd({ title, description, status, availability, prerequisite, completionRule, required, typeSettings })} className="h-11 rounded-full bg-[#1f6a58] px-5 text-sm font-extrabold text-white">Add {selectedType}</button></div></>;
}


